"""Pry PyPI Package Stats - generated by the Actor Factory.

PPE runtime: charges 'package-stats-pulled' per processed URL via push_data,
respects user spending limits (event_charge_limit_reached), and flushes
completed work on platform abort. See ACTOR-FACTORY.md for methodology.
"""

from __future__ import annotations

import asyncio
import sys
from pathlib import Path

# Make the repo root importable when running from a source checkout.
_REPO_ROOT = Path(__file__).resolve().parents[1]
if str(_REPO_ROOT) not in sys.path:
    sys.path.insert(0, str(_REPO_ROOT))

from actor_factory.runner import ActorRunConfig, PPEScraperRunner  # noqa: E402


async def main() -> None:
    runner = PPEScraperRunner(
        config=ActorRunConfig(
            primary_event="package-stats-pulled",
            default_output_format="markdown",
            processor_name="jsondata",
        ),
        actor_module=None,  # resolved lazily so tests can inject a mock
    )
    await runner.run()


if __name__ == "__main__":
    asyncio.run(main())
